/**
 * Render an inline icon. `$size` is in pixels; stroke scaling matches the
 * lucide default of 2 at 24px so icons stay visually consistent at any size.
 */
function icon(string $name, int $size = 16, string $class = ''): string {
    $paths = tg_icon_paths();
    $body = $paths[$name] ?? $paths['activity'];
    $cls = trim('lucide lucide-'.$name.($class !== '' ? ' '.$class : ''));
    return '<svg xmlns="http://www.w3.org/2000/svg" width="'.$size.'" height="'.$size
        .'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
        .' stroke-linecap="round" stroke-linejoin="round" class="'.h($cls).'" aria-hidden="true">'
        .$body.'</svg>';
}
